// Alibi Protocol Worker v5 - Clean build
// Landing page served at /, app at /app

const LANDING_B64 = "";
const APP_B64 = "";
const MANIFEST_STR = "{\"name\":\"Alibi Protocol\",\"short_name\":\"Alibi\",\"start_url\":\"/app\",\"display\":\"standalone\",\"theme_color\":\"#0A0A0C\",\"background_color\":\"#0A0A0C\"}";
const SW_STR = "\nconst CACHE = 'alibi-v4';\nconst OFFLINE_URL = '/';\nself.addEventListener('install', e => {\n  e.waitUntil(\n    caches.open(CACHE).then(c => c.addAll(['/'])).then(() => self.skipWaiting())\n  );\n});\nself.addEventListener('activate', e => {\n  e.waitUntil(\n    caches.keys().then(keys =>\n      Promise.all(keys.filter(k => k !== CACHE).map(k => caches.delete(k)))\n    ).then(() => self.clients.claim())\n  );\n});\nself.addEventListener('fetch', e => {\n  if(e.request.mode === 'navigate'){\n    e.respondWith(\n      fetch(e.request).catch(() => caches.match(OFFLINE_URL))\n    );\n    return;\n  }\n  e.respondWith(\n    caches.match(e.request).then(r => r || fetch(e.request))\n  );\n});\n";

function b64decode(s) {
  // atob() returns binary string (1 char=1 byte). Re-decode as UTF-8 so
  // multi-byte chars (arrows, dashes, etc.) are preserved correctly.
  if (typeof atob !== 'undefined') {
    const bytes = Uint8Array.from(atob(s), c => c.charCodeAt(0));
    return new TextDecoder('utf-8').decode(bytes);
  }
  return Buffer.from(s, 'base64').toString('utf-8');
}

const LANDING_HTML = b64decode(LANDING_B64);
const STYLES_B64 = "";
const STYLES_CSS = b64decode(STYLES_B64);

const APP_HTML = b64decode(APP_B64);
const AIRDROP_B64 = "";
const AIRDROP_HTML = b64decode(AIRDROP_B64);
const TOKENOMICS_B64 = "";
const TOKENOMICS_HTML = b64decode(TOKENOMICS_B64);


const PRIVACY_B64 = "";
const PRIVACY_HTML = b64decode(PRIVACY_B64);
const TERMS_B64 = "";
const TERMS_HTML = b64decode(TERMS_B64);


const CORS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
};


// ============================================================
// AIRDROP API HANDLER
// ============================================================
// ============================================================
// ALIBI PROTOCOL AIRDROP API — Cloudflare D1 Handler
// Injected into Worker v6. Access via env.DB (D1 binding).
// ============================================================

function nanoid(len=10) {
  const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  let s = '';
  const arr = new Uint8Array(len);
  crypto.getRandomValues(arr);
  for (let b of arr) s += chars[b % chars.length];
  return s;
}

function getTier(pts) {
  if (pts >= 10000) return 'ARCHITECT';
  if (pts >= 5000)  return 'GUARDIAN';
  if (pts >= 2000)  return 'SENTINEL';
  if (pts >= 500)   return 'OPERATIVE';
  return 'RECRUIT';
}

function jsonResp(data, status=200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { 'Content-Type': 'application/json', 'Access-Control-Allow-Origin': '*' }
  });
}

async function handleAirdropAPI(path, method, request, env) {
  const DB = env.DB;
  if (!DB) return jsonResp({ error: 'Database not configured' }, 500);

  // ── POST /register ─────────────────────────────────────────
  if (path === '/register' && method === 'POST') {
    const body = await request.json().catch(() => ({}));
    const { wallet_address, username, referral_code } = body;
    if (!wallet_address || !/^[1-9A-HJ-NP-Za-km-z]{32,44}$/.test(wallet_address))
      return jsonResp({ error: 'Invalid Solana wallet address' }, 400);

    const existing = await DB.prepare('SELECT * FROM airdrop_users WHERE wallet_address = ?')
      .bind(wallet_address).first();
    if (existing) return jsonResp({ user: existing, new: false });

    // Validate referral code
    let referrer = null;
    if (referral_code) {
      referrer = await DB.prepare('SELECT wallet_address FROM airdrop_users WHERE referral_code = ?')
        .bind(referral_code).first();
      // SECURITY: Prevent self-referral
      if (referrer && referrer.wallet_address === wallet) {
        referrer = null; // Silently ignore self-referral
      }
    }

    const myCode = nanoid(8);
    const cleanUser = username?.replace(/[^a-zA-Z0-9_]/g,'').slice(0,24) || null;

    // Check username uniqueness
    if (cleanUser) {
      const taken = await DB.prepare('SELECT 1 FROM airdrop_users WHERE username = ?').bind(cleanUser).first();
      if (taken) return jsonResp({ error: 'Username already taken' }, 409);
    }

    await DB.prepare(`INSERT INTO airdrop_users (wallet_address, username, referral_code, referred_by, total_points, tier)
      VALUES (?, ?, ?, ?, 0, 'RECRUIT')`)
      .bind(wallet_address, cleanUser, myCode, referrer?.wallet_address || null).run();

    // Award referral bonus
    if (referrer) {
      await DB.prepare('INSERT OR IGNORE INTO airdrop_referrals (referrer_wallet, referred_wallet) VALUES (?,?)')
        .bind(referrer.wallet_address, wallet_address).run();
    }

    const user = await DB.prepare('SELECT * FROM airdrop_users WHERE wallet_address = ?')
      .bind(wallet_address).first();
    return jsonResp({ user, new: true });
  }

  // ── GET /profile ───────────────────────────────────────────
  if (path.startsWith('/profile') && method === 'GET') {
    const wallet = new URL(request.url).searchParams.get('wallet');
    if (!wallet) return jsonResp({ error: 'wallet required' }, 400);
    const user = await DB.prepare('SELECT * FROM airdrop_users WHERE wallet_address = ?')
      .bind(wallet).first();
    if (!user) return jsonResp({ error: 'User not found' }, 404);
    const completions = await DB.prepare(
      'SELECT task_id, points_earned, completed_at FROM airdrop_completions WHERE wallet_address = ? ORDER BY completed_at DESC'
    ).bind(wallet).all();
    const rank = await DB.prepare(
      'SELECT COUNT(*)+1 as rank FROM airdrop_users WHERE total_points > ?'
    ).bind(user.total_points).first();
    const refCount = await DB.prepare(
      'SELECT COUNT(*) as cnt FROM airdrop_referrals WHERE referrer_wallet = ?'
    ).bind(wallet).first();
    return jsonResp({ user, completions: completions.results, rank: rank?.rank || 1, referral_count: refCount?.cnt || 0 });
  }

  // ── GET /tasks ─────────────────────────────────────────────
  if (path.startsWith('/tasks') && method === 'GET') {
    const wallet = new URL(request.url).searchParams.get('wallet');
    const tasks = await DB.prepare('SELECT * FROM airdrop_tasks WHERE is_active=1 ORDER BY sort_order').all();
    if (!wallet) return jsonResp({ tasks: tasks.results.map(t => ({ ...t, completed: false })) });
    const completions = await DB.prepare(
      'SELECT task_id FROM airdrop_completions WHERE wallet_address = ?'
    ).bind(wallet).all();
    const doneSet = new Set(completions.results.map(c => c.task_id));
    return jsonResp({ tasks: tasks.results.map(t => ({ ...t, completed: doneSet.has(t.task_id) })) });
  }

  // ── POST /complete ─────────────────────────────────────────
  if (path === '/complete' && method === 'POST') {
    const body = await request.json().catch(() => ({}));
    const { wallet_address, task_id, metadata } = body;
    if (!wallet_address || !task_id) return jsonResp({ error: 'wallet_address and task_id required' }, 400);

    const user = await DB.prepare('SELECT * FROM airdrop_users WHERE wallet_address = ?')
      .bind(wallet_address).first();
    if (!user) return jsonResp({ error: 'User not registered' }, 404);

    const task = await DB.prepare('SELECT * FROM airdrop_tasks WHERE task_id = ? AND is_active = 1')
      .bind(task_id).first();
    if (!task) return jsonResp({ error: 'Task not found' }, 404);

    // Check if already completed (for max_completions=1 tasks)
    if (task.max_completions === 1) {
      const done = await DB.prepare(
        'SELECT 1 FROM airdrop_completions WHERE wallet_address = ? AND task_id = ?'
      ).bind(wallet_address, task_id).first();
      if (done) return jsonResp({ error: 'Task already completed' }, 409);
    }

    // Check cooldown
    if (task.cooldown_seconds > 0) {
      const last = await DB.prepare(
        'SELECT completed_at FROM airdrop_completions WHERE wallet_address=? AND task_id=? ORDER BY completed_at DESC LIMIT 1'
      ).bind(wallet_address, task_id).first();
      if (last && (Math.floor(Date.now()/1000) - last.completed_at) < task.cooldown_seconds)
        return jsonResp({ error: 'Cooldown active — try again later' }, 429);
    }

    const metaStr = metadata ? JSON.stringify(metadata) : null;
    await DB.prepare(
      'INSERT INTO airdrop_completions (wallet_address, task_id, points_earned, metadata) VALUES (?,?,?,?)'
    ).bind(wallet_address, task_id, task.points, metaStr).run();

    const newPts = (user.total_points || 0) + task.points;
    const newTier = getTier(newPts);
    await DB.prepare('UPDATE airdrop_users SET total_points=?, tier=?, last_active=unixepoch() WHERE wallet_address=?')
      .bind(newPts, newTier, wallet_address).run();

    // Award referrer bonus when referred user completes first task
    if (user.referred_by) {
      const existingCompletions = await DB.prepare(
        'SELECT COUNT(*) as cnt FROM airdrop_completions WHERE wallet_address=?'
      ).bind(wallet_address).first();
      if (existingCompletions?.cnt === 1) {
        const REFERRAL_BONUS = 300;
        await DB.prepare('UPDATE airdrop_users SET total_points=total_points+?, last_active=unixepoch() WHERE wallet_address=?')
          .bind(REFERRAL_BONUS, user.referred_by).run();
        await DB.prepare('UPDATE airdrop_users SET tier=? WHERE wallet_address=?')
          .bind(getTier((await DB.prepare('SELECT total_points FROM airdrop_users WHERE wallet_address=?').bind(user.referred_by).first())?.total_points || 0), user.referred_by).run();
        await DB.prepare('UPDATE airdrop_referrals SET bonus_awarded=1 WHERE referrer_wallet=? AND referred_wallet=?')
          .bind(user.referred_by, wallet_address).run();
      }
    }

    return jsonResp({ success: true, points_earned: task.points, total_points: newPts, tier: newTier });
  }

  // ── GET /leaderboard ───────────────────────────────────────
  if (path.startsWith('/leaderboard') && method === 'GET') {
    const params = new URL(request.url).searchParams;
    const limit = Math.min(parseInt(params.get('limit') || '20'), 50);
    const offset = parseInt(params.get('offset') || '0');
    const users = await DB.prepare(
      'SELECT wallet_address, username, total_points, tier FROM airdrop_users ORDER BY total_points DESC LIMIT ? OFFSET ?'
    ).bind(limit, offset).all();
    const total = await DB.prepare('SELECT COUNT(*) as cnt FROM airdrop_users').first();
    return jsonResp({ users: users.results, total: total?.cnt || 0 });
  }

  // ── GET /stats ─────────────────────────────────────────────
  if (path.startsWith('/stats') && method === 'GET') {
    const [participants, points, tasks] = await Promise.all([
      DB.prepare('SELECT COUNT(*) as cnt FROM airdrop_users').first(),
      DB.prepare('SELECT COALESCE(SUM(total_points),0) as total FROM airdrop_users').first(),
      DB.prepare('SELECT COUNT(*) as cnt FROM airdrop_completions').first()
    ]);
    return jsonResp({
      total_participants: participants?.cnt || 0,
      total_points: points?.total || 0,
      tasks_completed: tasks?.cnt || 0
    });
  }

  // ── POST /update ───────────────────────────────────────────
  if (path === '/update' && method === 'POST') {
    const body = await request.json().catch(() => ({}));
    const { wallet_address, username } = body;
    if (!wallet_address) return jsonResp({ error: 'wallet_address required' }, 400);
    if (username) {
      const clean = username.replace(/[^a-zA-Z0-9_]/g,'').slice(0,24);
      if (!clean) return jsonResp({ error: 'Invalid username' }, 400);
      const taken = await DB.prepare('SELECT 1 FROM airdrop_users WHERE username=? AND wallet_address!=?')
        .bind(clean, wallet_address).first();
      if (taken) return jsonResp({ error: 'Username already taken' }, 409);
      await DB.prepare('UPDATE airdrop_users SET username=? WHERE wallet_address=?')
        .bind(clean, wallet_address).run();
    }
    const user = await DB.prepare('SELECT * FROM airdrop_users WHERE wallet_address=?')
      .bind(wallet_address).first();
    return jsonResp({ user });
  }

  return jsonResp({ error: 'Not found' }, 404);
}


export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const p = url.pathname;

    // ── www → apex 301 (consolidate to canonical host) ──
    if (url.hostname === 'www.alibiprotocol.com') {
      return Response.redirect('https://alibiprotocol.com' + p + url.search, 301);
    }

    if (request.method === 'OPTIONS') {
      return new Response(null, { status: 204, headers: CORS });
    }

    if (p === '/manifest.json') {
      return new Response(MANIFEST_STR, {
        headers: { 'Content-Type': 'application/manifest+json', 'Cache-Control': 'public,max-age=3600', ...CORS }
      });
    }

    if (p === '/sw.js') {
      return new Response(SW_STR, {
        headers: { 'Content-Type': 'application/javascript', 'Cache-Control': 'no-cache', ...CORS }
      });
    }

    // ── Favicon (inline SVG shield, no redirect loop) ──
    if (p === '/favicon.svg' || p === '/favicon.ico' || p === '/icon-192.png' || p === '/icon-512.png') {
      const SHIELD_SVG = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><defs><linearGradient id="g" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#00E5FF"/><stop offset="1" stop-color="#00FF87"/></linearGradient></defs><rect width="64" height="64" rx="12" fill="#020204"/><path d="M32 8 L52 16 V32 C52 44 42 54 32 58 C22 54 12 44 12 32 V16 Z" fill="none" stroke="url(#g)" stroke-width="3" stroke-linejoin="round"/><path d="M24 32 L30 38 L42 26" fill="none" stroke="url(#g)" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg>';
      return new Response(SHIELD_SVG, {
        headers: { 'Content-Type': 'image/svg+xml', 'Cache-Control': 'public,max-age=86400', ...CORS }
      });
    }

    // ── robots.txt ──
    if (p === '/robots.txt') {
      return new Response('User-agent: *\nAllow: /\nSitemap: https://alibiprotocol.com/sitemap.xml\n', {
        headers: { 'Content-Type': 'text/plain;charset=UTF-8', 'Cache-Control': 'public,max-age=86400', ...CORS }
      });
    }

    // ── og-image.png → inline SVG (browsers/social platforms accept SVG via Content-Type) ──
    if (p === '/og-image.png' || p === '/og-image.svg') {
      const OG_SVG = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 630"><defs><linearGradient id="bg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#020204"/><stop offset="1" stop-color="#0A0A0E"/></linearGradient><linearGradient id="g" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#00E5FF"/><stop offset="1" stop-color="#00FF87"/></linearGradient></defs><rect width="1200" height="630" fill="url(#bg)"/><g transform="translate(140,200)"><path d="M60 0 L120 24 V72 C120 108 90 138 60 150 C30 138 0 108 0 72 V24 Z" fill="none" stroke="url(#g)" stroke-width="6" stroke-linejoin="round"/><path d="M30 75 L52 96 L90 56" fill="none" stroke="url(#g)" stroke-width="6" stroke-linecap="round" stroke-linejoin="round"/></g><text x="320" y="280" font-family="Inter,sans-serif" font-size="72" font-weight="900" fill="#F8F7F3" letter-spacing="4">ALIBI PROTOCOL</text><text x="320" y="350" font-family="Inter,sans-serif" font-size="36" font-weight="600" fill="#00E5FF">Get Paid to Drive. Stay Protected.</text><text x="320" y="430" font-family="JetBrains Mono,monospace" font-size="22" font-weight="400" fill="#999">alibiprotocol.com</text></svg>';
      return new Response(OG_SVG, {
        headers: { 'Content-Type': 'image/svg+xml', 'Cache-Control': 'public,max-age=86400', ...CORS }
      });
    }

    if (p === '/app' || p === '/alibi-protocol-app') {
      return new Response(APP_HTML, {
        headers: {
          'Content-Type': 'text/html;charset=UTF-8',
          'Cache-Control': 'no-cache, no-store, must-revalidate',
          'X-Content-Type-Options': 'nosniff',
          'Permissions-Policy': 'microphone=(self), geolocation=(self), camera=(self)'
        }
      });
    }

    if (p === '/styles.css') {
      return new Response(STYLES_CSS, { headers: { 'Content-Type': 'text/css;charset=UTF-8', 'Cache-Control': 'public,max-age=86400', ...CORS } });
    }

    if (p === '/' || p === '' || p === '/home') {
      return new Response(LANDING_HTML, {
        headers: {
          'Content-Type': 'text/html;charset=UTF-8',
          'Cache-Control': 'no-cache, no-store, must-revalidate',
          'X-Content-Type-Options': 'nosniff'
        }
      });
    }

    
    // ── Token supply endpoints (required by Solscan/Birdeye registry) ──
    if (p === '/api/circulating-supply' || p === '/circulating-supply') {
      return new Response(JSON.stringify({ circulatingSupply: 1000000000 }), {
        headers: { 'Content-Type': 'application/json', 'Cache-Control': 'public,max-age=300', ...CORS }
      });
    }
    if (p === '/api/total-supply' || p === '/total-supply') {
      return new Response(JSON.stringify({ totalSupply: 1000000000 }), {
        headers: { 'Content-Type': 'application/json', 'Cache-Control': 'public,max-age=300', ...CORS }
      });
    }

    // ── Airdrop dashboard ──────────────────────────────────
    if (p === '/airdrop') {
      return new Response(AIRDROP_HTML, {
        headers: {
          'Content-Type': 'text/html;charset=UTF-8',
          'Cache-Control': 'no-cache, no-store, must-revalidate',
          'X-Content-Type-Options': 'nosniff'
        }
      });
    }

    // ── Airdrop API ────────────────────────────────────────
    if (p.startsWith('/api/airdrop/')) {
      if (request.method === 'OPTIONS') {
        return new Response(null, { status: 204, headers: {
          'Access-Control-Allow-Origin': '*',
          'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
          'Access-Control-Allow-Headers': 'Content-Type'
        }});
      }
      const apiPath = p.replace('/api/airdrop', '');
      return handleAirdropAPI(apiPath, request.method, request, env);
    }

    // ── Privacy & Terms (baked in, not redirected) ──
    if (p === '/privacy.html' || p === '/privacy') {
      return new Response(PRIVACY_HTML, {
        headers: { 'Content-Type': 'text/html;charset=UTF-8', 'Cache-Control': 'public,max-age=3600', 'X-Content-Type-Options': 'nosniff' }
      });
    }
    if (p === '/terms.html' || p === '/terms') {
      return new Response(TERMS_HTML, {
        headers: { 'Content-Type': 'text/html;charset=UTF-8', 'Cache-Control': 'public,max-age=3600', 'X-Content-Type-Options': 'nosniff' }
      });
    }

        // ── Tokenomics page ──
    if (p === '/tokenomics' || p === '/tokenomics.html') {
      return new Response(TOKENOMICS_HTML, {
        headers: { 'Content-Type': 'text/html;charset=UTF-8', 'Cache-Control': 'public,max-age=3600', 'X-Content-Type-Options': 'nosniff' }
      });
    }

// ── Legacy .html sub-pages → graceful fallback to apex landing ──
    if (p.endsWith('.html')) {
      return Response.redirect('https://alibiprotocol.com/', 301);
    }

    return new Response('Not found', { status: 404 });
  }
};
